test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // lineTotal: 100000, discount: 10000, afterDiscount: 90000, VAT: 90000 * 21 / 100 = 18900
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 10000);
  assert.equal(totals.vat, 18900);
  assert.equal(totals.total, 100000 - 10000 + 18900);
});

