test('invoiceTotals sums VAT from multiple lines with different rates', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 1, unitPrice: 10000, vatRate: 21, discountPercent: 0 },
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 1, unitPrice: 5000, vatRate: 9, discountPercent: 0 },
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 2000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: VAT = 10000 * 21 / 100 = 2100
  // Line 2: VAT = 5000 * 9 / 100 = 450
  // Line 3: VAT = 0
  assert.equal(totals.vat, 2100 + 450);
  assert.equal(totals.total, 10000 + 5000 + 2000 + 2100 + 450);
});

